DELETE
FROM t_prompt
WHERE source_id = #{sourceId}

    AND prompt_key NOT IN

        #{key}

mapper.select:
SELECT DISTINCT jt.tag FROM t_prompt p JOIN JSON_TABLE (p.tags_json, '$[*]' COLUMNS (tag VARCHAR(64) PATH '$')) jt WHERE p.user_id = #{userId}
AND p.source_id IN
#{sid}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.prompt LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY jt.tag LIMIT #{limit}
